<?php
declare(strict_types=1);
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Favicon ICO Generator — SmartToolz</title><meta name="description" content="Create a multi-size favicon.ico file directly in your browser."><link rel="stylesheet" href="/assets/css/smarttoolz.css"><style>.ico-wrap{max-width:1000px;margin:30px auto 70px;padding:0 16px}.ico-card{background:#fff;border:1px solid #e5e9f0;border-radius:20px;padding:24px;box-shadow:0 14px 40px rgba(20,30,70,.05)}.ico-grid{display:grid;grid-template-columns:320px 1fr;gap:20px}.ico-preview{display:grid;place-items:center;min-height:320px;background:#fafbff;border:1px solid #e5e9f0;border-radius:16px}.ico-preview canvas{width:240px;height:240px}.ico-controls{display:grid;gap:12px}.ico-field{padding:13px;background:#fafbff;border:1px solid #e5e9f0;border-radius:13px}.ico-field label{display:block;font-size:11px;font-weight:800;color:#707b8e;margin-bottom:7px}.ico-field input,.ico-field select{width:100%;height:40px;box-sizing:border-box;border:1px solid #d7dbea;border-radius:9px;padding:7px;background:#fff}.ico-sources,.ico-sizes{display:flex;flex-wrap:wrap;gap:7px}.ico-sources button,.ico-size{border:1px solid #dfe3eb;background:#fff;border-radius:9px;padding:9px 11px;cursor:pointer;font-weight:800;color:#4d5768}.ico-sources button.active,.ico-size.active{border-color:#635bff;background:#eeedff;color:#635bff}.ico-actions{display:flex;gap:8px;flex-wrap:wrap}.ico-actions button{border:0;border-radius:10px;padding:12px 16px;background:#635bff;color:#fff;font-weight:850;cursor:pointer}.ico-actions .secondary{background:#edf0f5;color:#344055}.ico-note{color:#707b8e;font-size:12px;line-height:1.6}@media(max-width:700px){.ico-grid{grid-template-columns:1fr}.ico-preview{min-height:260px}.ico-preview canvas{width:210px;height:210px}}</style></head><body><?php require_once dirname(__DIR__,2).'/header.php'; ?><main class="ico-wrap"><section class="ico-card"><span class="eyebrow">FREE ONLINE TOOL</span><h1>Favicon ICO Generator</h1><p class="ico-note">Build a multi-size <strong>favicon.ico</strong> locally in your browser. No account, database, tracking or external service.</p><div class="ico-grid"><div class="ico-preview"><canvas id="preview" width="256" height="256"></canvas></div><div class="ico-controls"><div class="ico-field"><label>Source</label><div class="ico-sources"><button class="active" data-source="image" type="button">Image</button><button data-source="emoji" type="button">Emoji</button><button data-source="text" type="button">Text</button></div><input id="file" type="file" accept="image/png,image/jpeg,image/webp,image/gif,image/svg+xml"><input id="emoji" type="text" value="🚀" maxlength="8" hidden><input id="text" type="text" value="S" maxlength="3" hidden></div><div class="ico-field"><label>Background</label><input id="bg" type="color" value="#FFFFFF"><label style="margin-top:9px">Foreground</label><input id="fg" type="color" value="#1537D4"><label style="margin-top:9px">Image Fit</label><select id="fit"><option value="contain">Contain</option><option value="cover">Cover</option></select></div><div class="ico-field"><label>ICO Sizes</label><div class="ico-sizes" id="sizes"></div></div><div class="ico-actions"><button id="generate" type="button">Generate favicon.ico</button><button class="secondary" id="reset" type="button">Reset</button></div><div class="ico-note" id="status">Choose a source and generate your ICO.</div></div></div></section></main><?php require_once dirname(__DIR__,2).'/footer.php'; ?><script>
(()=>{const $=id=>document.getElementById(id),p=$('preview'),px=p.getContext('2d');let source='image',img=null;const sizes=[16,24,32,48,64,96,128,256],chosen=new Set(sizes);sizes.forEach(s=>{const b=document.createElement('button');b.className='ico-size active';b.type='button';b.textContent=s+'×'+s;b.onclick=()=>{chosen.has(s)?chosen.delete(s):chosen.add(s);b.classList.toggle('active',chosen.has(s))};$('sizes').append(b)});function draw(c,size){const x=c.getContext('2d');x.fillStyle=$('bg').value;x.fillRect(0,0,size,size);if(source==='image'&&img){const contain=$('fit').value==='contain',scale=contain?Math.min(size/img.width,size/img.height):Math.max(size/img.width,size/img.height),w=img.width*scale,h=img.height*scale;x.drawImage(img,(size-w)/2,(size-h)/2,w,h)}else{x.fillStyle=$('fg').value;x.textAlign='center';x.textBaseline='middle';x.font=(source==='emoji'?Math.floor(size*.72):'800 '+Math.floor(size*.62))+'px Arial,sans-serif';x.fillText(source==='emoji'?($('emoji').value||'🚀'):($('text').value||'S'),size/2,size/2)}return c}function refresh(){draw(p,256)}document.querySelectorAll('[data-source]').forEach(b=>b.onclick=()=>{source=b.dataset.source;document.querySelectorAll('[data-source]').forEach(x=>x.classList.toggle('active',x===b));$('file').hidden=source!=='image';$('emoji').hidden=source!=='emoji';$('text').hidden=source!=='text';refresh()});$('file').onchange=e=>{const f=e.target.files?.[0];if(!f)return;const u=URL.createObjectURL(f),i=new Image();i.onload=()=>{img=i;URL.revokeObjectURL(u);$('status').textContent='Image ready.';refresh()};i.onerror=()=>URL.revokeObjectURL(u);i.src=u};['bg','fg','emoji','text','fit'].forEach(id=>$(id).addEventListener('input',refresh));async function png(c){return new Promise((res,rej)=>c.toBlob(b=>b?res(b):rej(new Error('PNG creation failed')),'image/png'))}async function makeIco(){const ss=[...chosen].sort((a,b)=>a-b);if(!ss.length)throw Error('Select at least one size.');const bufs=await Promise.all(ss.map(s=>png(draw(document.createElement('canvas'),s)).then(b=>b.arrayBuffer())));const header=6+16*ss.length,total=header+bufs.reduce((n,b)=>n+b.byteLength,0),out=new Uint8Array(total),dv=new DataView(out.buffer);dv.setUint16(0,0,true);dv.setUint16(2,1,true);dv.setUint16(4,ss.length,true);let off=header;bufs.forEach((b,i)=>{const s=ss[i],o=6+i*16;out[o]=s===256?0:s;out[o+1]=s===256?0:s;out[o+2]=0;out[o+3]=0;dv.setUint16(o+4,1,true);dv.setUint16(o+6,32,true);dv.setUint32(o+8,b.byteLength,true);dv.setUint32(o+12,off,true);out.set(new Uint8Array(b),off);off+=b.byteLength});return new Blob([out],{type:'image/x-icon'})}$('generate').onclick=async()=>{const b=$('generate');b.disabled=true;$('status').textContent='Generating...';try{const blob=await makeIco(),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='favicon.ico';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);$('status').textContent='favicon.ico generated successfully.'}catch(e){$('status').textContent=e.message||'Generation failed.'}b.disabled=false};$('reset').onclick=()=>{img=null;$('file').value='';$('bg').value='#FFFFFF';$('fg').value='#1537D4';$('fit').value='contain';source='image';$('file').hidden=false;$('emoji').hidden=true;$('text').hidden=true;document.querySelectorAll('.ico-size').forEach(x=>{x.classList.add('active');chosen.add(+x.textContent.split('×')[0])});refresh();$('status').textContent='Choose a source and generate your ICO.'};$('file').hidden=false;$('emoji').hidden=true;$('text').hidden=true;refresh()})();
</script></body></html>